fn numpy_argmin(a: Vec<i8>) -> usize {
    // Since `a` is guaranteed to be non-empty, we can safely initialize
    // the minimum value and index with the first element.
    let mut min_idx = 0;
    let mut min_val = a[0];

    // Iterate over the rest of the array starting from index 1.
    for (i, &val) in a.iter().enumerate().skip(1) {
        // Update if we find a strictly smaller value.
        if val < min_val {
            min_val = val;
            min_idx = i;
        }
    }

    min_idx
}

